    await writeLedger(fromId, toId, amount)
    const from = await tx.wallet.update({
      where: { userId: fromId },
      data: { balance: { decrement: amount } },
    })
    if (from.balance < 0) {
      throw new Error('Insufficient balance')
    }
    await tx.wallet.update({
      where: { userId: toId },
      data: { balance: { increment: amount } },
    })
  })
